class Solution {
public:
    long long MOD = 1e9 + 7;
    long long modPow(long long base, long long exp) {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
    long long modInverse(long long n) {
        return modPow(n, MOD - 2);
    }
    long long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        long long num = 1, den = 1;
        for (int i = 0; i < r; i++) {
            num = (num * (n - i)) % MOD;
            den = (den * (i + 1)) % MOD;
        }
        return (num * modInverse(den)) % MOD;
    }
    vector<int> waysToFillArray(vector<vector<int>>& queries) {
        vector<int> ans;
        for (const auto& q : queries) {
            int n = q[0], k = q[1];
            long long res = 1;
            for (int d = 2; d * d <= k; d++) {
                if (k % d == 0) {
                    int cnt = 0;
                    while (k % d == 0) {
                        cnt++;
                        k /= d;
                    }
                    res = (res * nCr(cnt + n - 1, cnt)) % MOD;
                }
            }
            if (k > 1) {
                res = (res * nCr(1 + n - 1, 1)) % MOD;
            }
            ans.push_back(res);
        }
        return ans;
    }
};

class Solution {
    private static final long MOD = 1_000_000_007L;
    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
    private long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        long num = 1, den = 1;
        for (int i = 0; i < r; i++) {
            num = (num * (n - i)) % MOD;
            den = (den * (i + 1)) % MOD;
        }
        return (num * modPow(den, MOD - 2)) % MOD;
    }
    public int[] waysToFillArray(int[][] queries) {
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int n = queries[i][0], k = queries[i][1];
            long res = 1;
            for (int d = 2; d * d <= k; d++) {
                if (k % d == 0) {
                    int cnt = 0;
                    while (k % d == 0) {
                        cnt++;
                        k /= d;
                    }
                    res = (res * nCr(cnt + n - 1, cnt)) % MOD;
                }
            }
            if (k > 1) {
                res = (res * nCr(1 + n - 1, 1)) % MOD;
            }
            ans[i] = (int)res;
        }
        return ans;
    }
}

var waysToFillArray = function(queries) {
    const MOD = 1000000007n;
    function modPow(base, exp) {
        let res = 1n;
        base = base % MOD;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }
    function nCr(n, r) {
        if (r < 0 || r > n) return 0n;
        let num = 1n, den = 1n;
        for (let i = 0; i < r; i++) {
            num = (num * BigInt(n - i)) % MOD;
            den = (den * BigInt(i + 1)) % MOD;
        }
        return (num * modPow(den, MOD - 2n)) % MOD;
    }
    const ans = [];
    for (const [n, k] of queries) {
        let currK = k;
        let res = 1n;
        for (let d = 2; d * d <= currK; d++) {
            if (currK % d === 0) {
                let cnt = 0;
                while (currK % d === 0) {
                    cnt++;
                    currK = Math.floor(currK / d);
                }
                res = (res * nCr(cnt + n - 1, cnt)) % MOD;
            }
        }
        if (currK > 1) {
            res = (res * nCr(1 + n - 1, 1)) % MOD;
        }
        ans.push(Number(res));
    }
    return ans;
};
